def main():
    import fcntl
    if os.geteuid()!=0:raise RuntimeError('Run as root')
    ROOT.mkdir(parents=True,exist_ok=True,mode=0o700)
    with open('/run/alirezaserver-update.lock','w') as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
