#!/usr/bin/env bash
# alirezaserver Hashem endpoint installer. Hashem remains AGPL-3.0.
# Only an explicit invocation performs installation. All tunnel changes use
# the same private paths, port checks and restore mechanism as the web panel.
set -Eeuo pipefail
umask 077
[[ $(id -u) == 0 ]] || { echo 'Run as root' >&2; exit 1; }
[[ ${1:-} =~ ^[A-Za-z0-9+/=]+$ ]] || { echo 'A generated configuration payload is required' >&2; exit 1; }
command -v python3 >/dev/null || { echo 'Python 3 is required' >&2; exit 1; }
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
base64 -d > "$work/hashem-manager.py" <<'PAYLOAD'

PAYLOAD
base64 -d > "$work/hashem-source.sh" <<'PAYLOAD'

PAYLOAD
base64 -d > "$work/reference-versions.json" <<'PAYLOAD'

PAYLOAD
base64 -d > "$work/tunnel-downloads.json" <<'PAYLOAD'

PAYLOAD
base64 -d > "$work/hashem-core-build.json" <<'PAYLOAD'

PAYLOAD
base64 -d > "$work/COPYING.Hashem" <<'PAYLOAD'

PAYLOAD
printf '%s' "$1" | base64 -d > "$work/config.json"
python3 -c 'import json,sys;v=json.load(open(sys.argv[1]));v["operation"]="validate";print(json.dumps(v))' "$work/config.json" | python3 "$work/hashem-manager.py" >/dev/null
case $(uname -m) in x86_64) arch=amd64;; aarch64) arch=arm64;; *) echo 'Unsupported architecture' >&2; exit 1;; esac
[[ "$arch" != amd64 ]] || expected=b652d4f1aa2f042196984cff63aafa2d1479d6b64ba1f82c98d21bcf47aacc07
[[ "$arch" != arm64 ]] || expected=8b2ae195cadab27e3fb1451b8302e42d47086ae1c53dbff8717b10f390b8e9c6
curl -fL --proto '=https' --tlsv1.2 --connect-timeout 15 --max-time 180 --retry 2 "https://raw.githubusercontent.com/alirezachatgpt97-coder/alirezaserver/main/addon/hashem-core-${arch}.b64" -o "$work/hashem-core-${arch}.b64"
printf '%s  %s\n' "$expected" "$work/hashem-core-${arch}.b64" | sha256sum -c -
printf '{"operation":"install"}' | python3 "$work/hashem-manager.py"
printf '%s' "$1" | base64 -d | python3 -c 'import json,sys;v=json.load(sys.stdin);v["operation"]="setup";print(json.dumps(v))' | python3 "$work/hashem-manager.py"
