    } elseif ($op === 'migrate') {
        $migration = require $destination;
        $migration($pdo);
        echo json_encode(['migrated'=>true]);
    } else throw new RuntimeException('BOT_INVALID_OPERATION');
} catch (Throwable $e) {
    while (ob_get_level()) ob_end_clean();
    $code = $e instanceof PDOException ? 'BOT_DATABASE_ERROR_' . preg_replace('/[^A-Z0-9]/','',(string)$e->getCode()) : (preg_match('/^BOT_[A-Z_]+$/', $e->getMessage()) ? $e->getMessage() : 'BOT_SCHEMA_REPAIR_FAILED');
    fwrite(STDERR, $code . "\n");
    exit(1);
}
