import * as shop from './shop.mjs';import {telegram} from './shop-worker.mjs';
export async function shopAPI(auth,operation,input,context){const owner=shop.ownerOf(auth),native=context.native(owner);
 if(operation==='catalog')return shop.catalog(owner,native);
 if(operation==='config')return shop.config(owner);
 if(operation==='configure')return shop.configure(owner,input,{telegram,mainToken:context.mainToken});
