// SPDX-License-Identifier: GPL-3.0-or-later
// Native sessions retain the seller's actual identity and Nova-enforced scope/quota.
import http from 'node:http';import {pathToFileURL} from 'node:url';
let kv,auth;const sessions=new Map();
export function scopedNative(owner,port,base){return async(route,method='GET',data)=>{if(!auth){const dir=process.env.ALIREZA_NOVA_DIR||'/opt/nova-node-agent';({openKv:kv}=await import(pathToFileURL(dir+'/src/kv/sqlite.mjs')));kv=kv(process.env.NOVA_DB||'/var/lib/nova/nova.db');auth=await import(pathToFileURL(dir+'/src/auth.mjs'));}let entry=sessions.get(owner);if(!entry||Date.now()-entry.at>60000){const s=await auth.makeSession(kv,{userAgent:'alirezashop-service',...(owner==='owner'?{}:{adminId:owner})});entry={at:Date.now(),cookie:s.name+'='+s.value};if(sessions.size>256)sessions.delete(sessions.keys().next().value);sessions.set(owner,entry);}return new Promise((resolve,reject)=>{const host='127.0.0.1:'+port;const r=http.request({hostname:'127.0.0.1',port,path:base+route,method,timeout:30000,headers:{host,origin:'http://'+host,cookie:entry.cookie,'user-agent':'alirezashop-service','content-type':'application/json'}},res=>{let text='';res.on('data',b=>{text+=b;if(text.length>8*1024*1024)r.destroy(Error('SHOP_NATIVE_RESPONSE_SIZE'));});res.on('end',()=>{try{const j=JSON.parse(text);if(res.statusCode>=400){sessions.delete(owner);throw Object.assign(Error(j.error||'SHOP_NATIVE_ERROR'),{status:res.statusCode});}resolve(j);}catch(e){reject(e);}});});r.on('timeout',()=>r.destroy(Error('SHOP_NATIVE_TIMEOUT')));r.on('error',reject);r.end(data?JSON.stringify(data):undefined);});};}
export async function verifyOwnerPassword(password){if(!auth||!kv)throw Error('SHOP_NATIVE_NOT_READY');return auth.checkPassword(kv,String(password));}
