// SPDX-License-Identifier: GPL-3.0-or-later
// Durable, scoped commerce. Wallet reservation and order creation are atomic.
import {verifyOwnerPassword} from './shop-native.mjs';
import {DatabaseSync} from 'node:sqlite';import fs from 'node:fs';import {randomBytes,createHash,randomUUID} from 'node:crypto';import {seal,unseal} from './vault.mjs';
const root=process.env.ALIREZA_ROOT||'/var/lib/alirezaserver',id=()=>randomBytes(16).toString('hex'),err=(code,status=400)=>Object.assign(Error(code),{status,code});let db;
export function database(){if(db)return db;fs.mkdirSync(root,{recursive:true,mode:0o700});db=new DatabaseSync(root+'/shop.db');db.exec(`PRAGMA journal_mode=WAL;PRAGMA busy_timeout=5000;PRAGMA wal_autocheckpoint=256;PRAGMA journal_size_limit=8388608;
CREATE TABLE IF NOT EXISTS shops(owner TEXT PRIMARY KEY,config TEXT NOT NULL,token_hash TEXT UNIQUE,next_poll INTEGER NOT NULL DEFAULT 0,offset INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS plan_grants(id TEXT PRIMARY KEY,owner TEXT NOT NULL,secret TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY,owner TEXT NOT NULL,data TEXT NOT NULL,active INTEGER NOT NULL,updated INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS plans_owner ON plans(owner,updated);
CREATE TABLE IF NOT EXISTS selections(owner TEXT NOT NULL,buyer TEXT NOT NULL,plan TEXT NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(owner,buyer));
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,owner TEXT NOT NULL,buyer TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wallets(owner TEXT NOT NULL,buyer TEXT NOT NULL,balance INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,buyer));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,owner TEXT NOT NULL,buyer TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL,credentials TEXT,lease INTEGER NOT NULL DEFAULT 0,error TEXT,created INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS orders_owner ON orders(owner,created);
CREATE TABLE IF NOT EXISTS credits(id TEXT PRIMARY KEY,owner TEXT NOT NULL,buyer TEXT NOT NULL,amount INTEGER NOT NULL,proof TEXT,status TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(owner,proof));
CREATE TABLE IF NOT EXISTS inbox(owner TEXT NOT NULL,seq INTEGER NOT NULL,payload TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,PRIMARY KEY(owner,seq));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL,next_try INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS quotes_created ON quotes(created);CREATE INDEX IF NOT EXISTS order_work ON orders(status,lease);CREATE INDEX IF NOT EXISTS credit_owner ON credits(owner,created);CREATE INDEX IF NOT EXISTS inbox_work ON inbox(owner,done,seq);CREATE INDEX IF NOT EXISTS inbox_cleanup ON inbox(done,created);CREATE INDEX IF NOT EXISTS outbox_work ON outbox(next_try,created);CREATE INDEX IF NOT EXISTS shop_poll ON shops(next_poll);`);fs.chmodSync(root+'/shop.db',0o600);return db;}
const tx=f=>{const d=database();d.exec('BEGIN IMMEDIATE');try{const r=f(d);d.exec('COMMIT');return r;}catch(e){d.exec('ROLLBACK');throw e;}};
export const ownerOf=auth=>{if(!auth||!['owner','admin','reseller','manager','admin1'].includes(auth.role))throw err('SHOP_FORBIDDEN',403);if(auth.role!=='owner'&&!auth.caps?.includes('users.create'))throw err('SHOP_CREATE_PERMISSION_REQUIRED',403);if(auth.role!=='owner'&&(!auth.id||String(auth.id)==='owner'))throw err('SHOP_IDENTITY_MISSING',403);return auth.role==='owner'?'owner':String(auth.id);};
const buyerId=v=>{v=String(v);if(!/^[1-9][0-9]{0,19}$/.test(v))throw err('SHOP_INVALID_BUYER');return v;};
const integer=(v,min,max)=>{const n=Number(v);if(!Number.isSafeInteger(n)||n<min||n>max)throw err('SHOP_INVALID_NUMBER');return n;};
const json=row=>row?JSON.parse(row.data):null;
export function config(owner,privateData=false){const row=database().prepare('SELECT config FROM shops WHERE owner=?').get(owner);const c=row?unseal(JSON.parse(row.config),'shop-config'):{};return privateData?c:{enabled:!!c.enabled,hasToken:!!c.token,username:c.username||'',paymentInstructions:c.paymentInstructions||'',adminChat:c.adminChat||'',lastError:c.lastError||'',lastDeliveryError:c.lastDeliveryError||'',pendingDeliveries:database().prepare('SELECT count(*) AS n FROM outbox WHERE owner=?').get(owner).n,pendingOrders:database().prepare("SELECT count(*) AS n FROM orders WHERE owner=? AND status IN ('reserved','provisioning','review')").get(owner).n};}
export async function configure(owner,v,{telegram,mainToken}){const old=config(owner,true),c={...old};if(v.deleteToken){delete c.token;delete c.username;c.enabled=false;}if(v.token){const token=String(v.token).trim();if(!/^\d{5,16}:[A-Za-z0-9_-]{20,100}$/.test(token)||mainToken?.(token))throw err('SHOP_INVALID_OR_MAIN_TOKEN');const me=await telegram(token,'getMe',{});if(!me?.username)throw err('SHOP_BOT_TOKEN_REJECTED');if(c.token!==token){c.epoch=id();}c.token=token;c.username=me.username;}if(v.enabled!==undefined)c.enabled=v.enabled===true;if(c.enabled&&!c.token)throw err('SHOP_TOKEN_REQUIRED');if(v.paymentInstructions!==undefined)c.paymentInstructions=String(v.paymentInstructions).slice(0,4000);if(v.adminChat!==undefined){c.adminChat=String(v.adminChat);if(c.adminChat&&!/^-?\d{1,20}$/.test(c.adminChat))throw err('SHOP_INVALID_ADMIN_CHAT');}const hash=c.token?createHash('sha256').update(c.token).digest('hex'):null;try{database().prepare('INSERT INTO shops(owner,config,token_hash) VALUES(?,?,?) ON CONFLICT(owner) DO UPDATE SET config=excluded.config,token_hash=excluded.token_hash').run(owner,JSON.stringify(seal(c,'shop-config')),hash);}catch(e){if(String(e).includes('UNIQUE'))throw err('SHOP_TOKEN_ALREADY_ASSIGNED',409);throw e;}if(old.token!==c.token){tx(d=>{d.prepare('UPDATE shops SET offset=0,next_poll=0 WHERE owner=?').run(owner);d.prepare('DELETE FROM inbox WHERE owner=?').run(owner);});}return config(owner);}
export async function catalog(owner,native){const who=await native('/admin/whoami');if(owner!=='owner'&&String(who.id)!==owner)throw err('SHOP_IDENTITY_MISMATCH',403);const network=owner==='owner'?await native('/admin/inbounds'):await native('/admin/users.json');let inbounds=network.inbounds||[];if(owner!=='owner'&&Array.isArray(who.selling?.inboundIds))inbounds=inbounds.filter(i=>who.selling.inboundIds.includes(i.id));const admins=owner==='owner'?await native('/admin/admins'):null;return{who,inbounds:inbounds.filter(i=>i.enabled!==false).map(({id,remark,protocol,port})=>({id,remark,protocol,port})),caps:admins?.capsCatalog||[],roles:admins?.roles||[]};}
export async function savePlan(owner,input,native){const c=await catalog(owner,native),kind=input.kind==='admin'?'admin':'user';if(kind==='admin'&&owner!=='owner')throw err('SHOP_ADMIN_SALE_OWNER_ONLY',403);const name=String(input.name||'').trim();if(!name||name.length>120)throw err('SHOP_PLAN_NAME_REQUIRED');const plan={name,kind,pricing:input.pricing==='volume'?'volume':'fixed',unitPrice:integer(input.unitPrice||0,0,1e9),minGB:integer(input.minGB||1,1,1000000),maxGB:integer(input.maxGB||1000,1,1000000),price:integer(input.price,0,1e12),quotaBytes:integer(input.quotaBytes,0,Number.MAX_SAFE_INTEGER),days:integer(input.days||30,1,3650),maxUsers:integer(input.maxUsers||1,1,1000000),geoExits:input.geoExits===true,inboundIds:Array.isArray(input.inboundIds)?[...new Set(input.inboundIds.map(String))]:[]};if(owner!=='owner'&&plan.geoExits&&c.who.selling?.allowGeo!==true)throw err('SHOP_GEO_NOT_GRANTED',403);if(plan.maxGB<plan.minGB)throw err('SHOP_INVALID_VOLUME_RANGE');if(plan.pricing==='volume'&&plan.unitPrice<1)throw err('SHOP_PRICE_PER_GB_REQUIRED');if(!plan.inboundIds.length||plan.inboundIds.some(i=>!c.inbounds.some(x=>x.id===i)))throw err('SHOP_SELECT_AVAILABLE_INBOUNDS');if(kind==='admin'){plan.role=String(input.role||'reseller');if(!c.roles.includes(plan.role)||plan.role==='owner')throw err('SHOP_INVALID_ROLE');plan.caps=Array.isArray(input.caps)?[...new Set(input.caps.map(String))]:[];if(plan.caps.some(x=>!c.caps.includes(x)))throw err('SHOP_INVALID_CAPABILITY');if(plan.role!=='reseller'){if(plan.pricing==='volume')throw err('SHOP_VOLUME_REQUIRES_RESELLER');plan.quotaBytes=0;plan.maxUsers=0;plan.days=0;}}if((kind==='user'||plan.role==='reseller')&&plan.quotaBytes<1)throw err('SHOP_POSITIVE_QUOTA_REQUIRED');const planId=input.id?String(input.id):id();if(input.id&&!database().prepare('SELECT id FROM plans WHERE id=? AND owner=?').get(planId,owner))throw err('SHOP_PLAN_NOT_FOUND',404);if(kind==='admin'&&plan.role==='admin1'){if(input.ownerPassword){if(!await verifyOwnerPassword(input.ownerPassword))throw err('SHOP_OWNER_PASSWORD_INVALID',403);database().prepare('INSERT INTO plan_grants VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET secret=excluded.secret WHERE owner=excluded.owner').run(planId,owner,JSON.stringify(seal({password:String(input.ownerPassword)},'shop-grant')));}if(!database().prepare('SELECT id FROM plan_grants WHERE id=? AND owner=?').get(planId,owner))throw err('SHOP_OWNER_APPROVAL_REQUIRED');}database().prepare('INSERT INTO plans VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data,active=excluded.active,updated=excluded.updated WHERE owner=excluded.owner').run(planId,owner,JSON.stringify(plan),input.active===false?0:1,Date.now());return{id:planId,...plan,active:input.active!==false};}
export function plans(owner,{active=false,offset=0,limit=100,kind}={}){offset=integer(offset,0,1e9);limit=integer(limit,1,100);return database().prepare('SELECT * FROM plans WHERE owner=?'+(active?' AND active=1':'')+(['admin','user'].includes(kind)?" AND json_extract(data,'$.kind')=?":'')+' ORDER BY updated DESC LIMIT ? OFFSET ?').all(...(['admin','user'].includes(kind)?[owner,kind,limit+1,offset]:[owner,limit+1,offset])).map(r=>({id:r.id,...json(r),active:!!r.active}));}
export function archive(owner,plan){database().prepare('UPDATE plans SET active=0 WHERE owner=? AND id=?').run(owner,String(plan));return{ok:true};}
export function quote(owner,buyer,planId,units){buyer=buyerId(buyer);const row=database().prepare('SELECT * FROM plans WHERE owner=? AND id=? AND active=1').get(owner,String(planId));if(!row)throw err('SHOP_PLAN_UNAVAILABLE',404);const plan={...json(row),planId:row.id};if(plan.pricing==='volume'){const gb=integer(units,plan.minGB,plan.maxGB);plan.quotaBytes=integer(gb*1073741824,1,Number.MAX_SAFE_INTEGER);plan.price=integer(gb*plan.unitPrice,1,1e12);plan.units=gb;}const q={id:id(),owner,buyer,plan,created:Date.now()};database().prepare('INSERT INTO quotes VALUES(?,?,?,?,?)').run(q.id,owner,buyer,JSON.stringify(q.plan),q.created);return q;}
export function getQuote(owner,buyer,qid){const row=database().prepare('SELECT * FROM quotes WHERE id=? AND owner=? AND buyer=?').get(String(qid),owner,buyerId(buyer));if(!row)throw err('SHOP_QUOTE_NOT_FOUND',404);return{id:row.id,owner,buyer:row.buyer,plan:json(row),created:row.created};}
export function balance(owner,buyer){return Number(database().prepare('SELECT balance FROM wallets WHERE owner=? AND buyer=?').get(owner,buyerId(buyer))?.balance||0);}
export function requestCredit(owner,buyer,amount,proof){buyer=buyerId(buyer);amount=integer(amount,1,1e12);proof=String(proof||id()).slice(0,500);const creditId=id();database().prepare("INSERT OR IGNORE INTO credits VALUES(?,?,?,?,?,'pending',?)").run(creditId,owner,buyer,amount,proof,Date.now());return{ok:true,id:database().prepare('SELECT id FROM credits WHERE owner=? AND proof=?').get(owner,proof).id};}
export function credits(owner,offset=0){return database().prepare('SELECT * FROM credits WHERE owner=? ORDER BY created DESC LIMIT 101 OFFSET ?').all(owner,integer(offset,0,1e9));}
export function decideCredit(owner,creditId,approve){return tx(d=>{const row=d.prepare('SELECT * FROM credits WHERE id=? AND owner=?').get(String(creditId),owner);if(!row)throw err('SHOP_CREDIT_NOT_FOUND',404);if(row.status!=='pending')return{ok:true,status:row.status};if(approve){if(balance(owner,row.buyer)+row.amount>Number.MAX_SAFE_INTEGER)throw err('SHOP_BALANCE_OVERFLOW');d.prepare('INSERT INTO wallets VALUES(?,?,?) ON CONFLICT(owner,buyer) DO UPDATE SET balance=balance+excluded.balance').run(owner,row.buyer,row.amount);}d.prepare('UPDATE credits SET status=? WHERE id=? AND owner=?').run(approve?'approved':'rejected',row.id,owner);return{ok:true,status:approve?'approved':'rejected'};});}
export function orders(owner,buyer,offset=0){offset=integer(offset,0,1e9);return database().prepare('SELECT id,buyer,data,status,error,created FROM orders WHERE owner=?'+(buyer?' AND buyer=?':'')+' ORDER BY created DESC LIMIT 101 OFFSET ?').all(...(buyer?[owner,buyerId(buyer),offset]:[owner,offset])).map(r=>{const data=json(r);delete data.password;return{...r,data};});}
export function order(owner,buyer,orderId,{credentials=false}={}){const r=database().prepare('SELECT * FROM orders WHERE owner=? AND buyer=? AND id=?').get(owner,buyerId(buyer),String(orderId));if(!r)throw err('SHOP_ORDER_NOT_FOUND',404);return{id:r.id,status:r.status,error:r.error,...(credentials&&r.status==='ready'?{credentials:unseal(JSON.parse(r.credentials),'shop-order')}:{}),plan:json(r).plan};}
export async function purchase(owner,buyer,qid,native,{externalPaid=false,panelURL}={}){buyer=buyerId(buyer);const identity=await native('/admin/whoami');if(owner!=='owner'&&(String(identity.id)!==owner||!identity.caps?.includes('users.create')))throw err('SHOP_IDENTITY_MISMATCH',403);let row=database().prepare('SELECT * FROM orders WHERE id=? AND owner=? AND buyer=?').get(String(qid),owner,buyer);if(!row){const q=getQuote(owner,buyer,qid);if(owner!=='owner'&&identity.selling?.mode==='volume'&&((identity.selling.remainingBytes!==undefined&&q.plan.quotaBytes>identity.selling.remainingBytes)||(identity.selling.remainingUsers!==undefined&&identity.selling.remainingUsers<=0)))throw err('SHOP_NATIVE_QUOTA_LOW',409);if(Date.now()-q.created>900000)throw err('SHOP_QUOTE_EXPIRED');await validateGrant(q.plan);const password=randomBytes(24).toString('base64url'),data={plan:q.plan,name:'shop-'+q.id.slice(0,20),password:seal({password},'shop-password'),externalPaid};tx(d=>{if(d.prepare('SELECT id FROM orders WHERE id=?').get(q.id))return;if(!externalPaid){const n=d.prepare('UPDATE wallets SET balance=balance-? WHERE owner=? AND buyer=? AND balance>=?').run(q.plan.price,owner,buyer,q.plan.price);if(!n.changes&&q.plan.price!==0)throw err('SHOP_INSUFFICIENT_BALANCE',409);}d.prepare("INSERT INTO orders(id,owner,buyer,data,status,created) VALUES(?,?,?,?,'reserved',?)").run(q.id,owner,buyer,JSON.stringify(data),Date.now());});}
 row=database().prepare('SELECT * FROM orders WHERE id=? AND owner=? AND buyer=?').get(String(qid),owner,buyer);if(row.status==='cancelled')throw err('SHOP_ORDER_CANCELLED',409);if(row.status==='awaiting_payment'){if(!externalPaid)throw err('SHOP_PAYMENT_REQUIRED',409);database().prepare("UPDATE orders SET status='reserved' WHERE id=? AND owner=? AND status='awaiting_payment'").run(qid,owner);}if(row.status==='ready')return order(owner,buyer,qid,{credentials:true});if(row.lease>Date.now())return order(owner,buyer,qid);const lease=Date.now()+120000;const claim=database().prepare("UPDATE orders SET lease=?,status='provisioning' WHERE id=? AND owner=? AND lease<=? AND status!='ready'").run(lease,qid,owner,Date.now());if(!claim.changes)return order(owner,buyer,qid);const data=json(row),p=data.plan,password=unseal(data.password,'shop-password').password;try{let result;if(p.kind==='admin'){if(owner!=='owner')throw err('SHOP_ADMIN_SALE_OWNER_ONLY',403);const list=await native('/admin/admins');const existing=list.admins?.find(a=>a.name===data.name);if(!existing)await native('/admin/admins','POST',{name:data.name,password,role:p.role,caps:p.caps,...(p.role==='reseller'?{mode:'volume',quotaBytes:p.quotaBytes,maxUsers:p.maxUsers,custExpireDays:p.days,inboundIds:p.inboundIds,allowGeo:p.geoExits}:{}),...(p.role==='admin1'?{ownerPassword:await validateGrant(p)}:{}),note:'Alirezabot order '+qid});const current=(await native('/admin/admins')).admins?.find(a=>a.name===data.name);if(!current)throw err('SHOP_ADMIN_NOT_CONFIRMED',502);result={username:data.name,password,panelURL,adminId:current.id};}else{const settings=await native(owner==='owner'?'/admin/network-settings.json':'/admin/users.json');let user=(settings.users||[]).find(u=>u.name===data.name);if(!user){user={id:'shop-'+qid,uuid:randomUUID(),name:data.name,email:data.name,enabled:true,quotaBytes:p.quotaBytes,expiry:new Date(Date.now()+p.days*86400000).toISOString(),inboundIds:p.inboundIds,geoExits:p.geoExits,note:'Alirezabot order '+qid};const created=await native('/admin/users.json','POST',{action:'add',user});if(created.apply?.ok===false)throw err('SHOP_CORE_APPLY_FAILED',502);}const links=await native('/admin/user-links?id='+encodeURIComponent(user.id));if(!links.subUrl||!links.links?.length)throw err('SHOP_NO_CONNECTION_LINKS',409);result={username:data.name,subscriptionUrl:links.subUrl,configs:links.links.map(l=>l.uri).filter(Boolean)};}database().prepare("UPDATE orders SET status='ready',credentials=?,lease=0,error=NULL WHERE id=? AND owner=?").run(JSON.stringify(seal(result,'shop-order')),qid,owner);}catch(e){database().prepare("UPDATE orders SET status='review',lease=strftime('%s','now')*1000+90000,error=? WHERE id=? AND owner=?").run(String(e.code||e.message||'SHOP_PROVISION_FAILED').slice(0,300),qid,owner);throw e;}return order(owner,buyer,qid,{credentials:true});}
export function cleanup(){const d=database();d.prepare('DELETE FROM quotes WHERE created<? AND id NOT IN (SELECT id FROM orders)').run(Date.now()-86400000);d.prepare('DELETE FROM inbox WHERE done=1 AND created<?').run(Date.now()-7*86400000);}

export function reserveExternal(owner,buyer,qid){const q=getQuote(owner,buyer,qid);if(Date.now()-q.created>900000&&!database().prepare('SELECT id FROM orders WHERE id=? AND owner=? AND buyer=?').get(qid,owner,String(buyer)))throw err('SHOP_QUOTE_EXPIRED');const data={plan:q.plan,name:'shop-'+q.id.slice(0,20),password:seal({password:randomBytes(24).toString('base64url')},'shop-password'),externalPaid:true};database().prepare("INSERT OR IGNORE INTO orders(id,owner,buyer,data,status,created) VALUES(?,?,?,?,'awaiting_payment',?)").run(q.id,owner,q.buyer,JSON.stringify(data),Date.now());return{ok:true,id:q.id};}
export async function cancel(owner,orderId,native){const row=database().prepare('SELECT * FROM orders WHERE id=? AND owner=?').get(String(orderId),owner);if(!row)throw err('SHOP_ORDER_NOT_FOUND',404);if(row.status==='cancelled')return{ok:true,externalPaid:json(row).externalPaid,buyer:row.buyer};if(!['review','reserved','awaiting_payment'].includes(row.status)||row.lease>Date.now()||Date.now()-row.created<120000)throw err('SHOP_CANCEL_NOT_SAFE_YET',409);const data=json(row);const all=data.plan.kind==='admin'?(await native('/admin/admins')).admins:(await native(owner==='owner'?'/admin/network-settings.json':'/admin/users.json')).users;if(all?.some(x=>x.name===data.name))throw err('SHOP_ACCOUNT_EXISTS_RETRY_DELIVERY',409);tx(d=>{const n=d.prepare("UPDATE orders SET status='cancelled' WHERE id=? AND owner=? AND lease<=? AND status IN ('review','reserved','awaiting_payment')").run(orderId,owner,Date.now());if(!n.changes)throw err('SHOP_ORDER_BUSY',409);if(!data.externalPaid)d.prepare('INSERT INTO wallets VALUES(?,?,?) ON CONFLICT(owner,buyer) DO UPDATE SET balance=balance+excluded.balance').run(owner,row.buyer,data.plan.price);});return{ok:true,externalPaid:data.externalPaid,buyer:row.buyer};}
export function queueMessage(owner,chat,text,key){database().prepare('INSERT OR IGNORE INTO outbox VALUES(?,?,?,?,0,0)').run(key||id(),owner,JSON.stringify(seal({chat_id:String(chat),text:String(text).slice(0,4000)},'shop-outbox')),Date.now());}

export async function validateGrant(plan){if(plan.kind!=='admin'||plan.role!=='admin1')return '';const grant=database().prepare('SELECT secret FROM plan_grants WHERE id=? AND owner=?').get(plan.planId,'owner');if(!grant)throw err('SHOP_OWNER_APPROVAL_REQUIRED');const password=unseal(JSON.parse(grant.secret),'shop-grant').password;if(!await verifyOwnerPassword(password))throw err('SHOP_OWNER_APPROVAL_EXPIRED');return password;}

export function findPlan(owner,planId){const row=database().prepare('SELECT * FROM plans WHERE owner=? AND id=? AND active=1').get(owner,String(planId));if(!row)throw err('SHOP_PLAN_UNAVAILABLE',404);return{id:row.id,...json(row),active:true};}
export function findOrder(owner,orderId){const r=database().prepare('SELECT buyer,data,status FROM orders WHERE owner=? AND id=?').get(owner,String(orderId));if(!r)throw err('SHOP_ORDER_NOT_FOUND',404);return{buyer:r.buyer,status:r.status,data:json(r)};}
