for item in os.environ.get('DNS_ALLOWED_CIDRS','').split(','):
    if item.strip():allowed.append(str(ipaddress.ip_network(item.strip(),strict=False)))
config={
 'http':{'address':'127.0.0.1:18085'},'users':[],
