# instances configured as enabled, with repaired configs and unchanged accounts.
ADDON_AFTER=$(find "$APP" -maxdepth 1 -type f -print0 | sort -z | xargs -0 -r sha256sum | sha256sum | cut -d ' ' -f 1)
ADDON_CHANGED=0;[[ "$ADDON_BEFORE" == "$ADDON_AFTER" ]] || ADDON_CHANGED=1
mkdir -p "$ROOT/openvpn"
OV_CONFIG_AFTER=$(find "$ROOT/openvpn" -name server.conf -type f -print0 2>/dev/null | sort -z | xargs -0 -r sha256sum | sha256sum | cut -d ' ' -f 1)
OV_CHANGED=0
if [[ "$OV_UNIT_BEFORE" != "$(artifact_hash /etc/systemd/system/alireza-openvpn@.service)" || "$OV_CONFIG_BEFORE" != "$OV_CONFIG_AFTER" ]]; then OV_CHANGED=1;fi
export FW_CHANGED OV_CHANGED
node --input-type=module - <<'JS'
import{servers,run,ready}from'/opt/alirezaserver/backend.mjs';
for(const s of servers())if(s.enabled){const u='alireza-openvpn@'+s.id+'.service';const active=await run('systemctl',['is-active',u]).catch(()=> '');if(active.trim()!=='active'||process.env.FW_CHANGED==='1'||process.env.OV_CHANGED==='1'){await run('systemctl',['restart',u]);await ready(s);}}
JS
if [[ "$ADDON_CHANGED" == 1 || "$DROPIN_BEFORE" != "$(artifact_hash "$DROPIN")" ]]; then systemctl restart nova-agent.service; else systemctl start nova-agent.service; fi
python3 - <<'PY'
import json,pathlib
p=pathlib.Path('/var/lib/alirezaserver/nova-source.json')
if not p.exists():
    import hashlib,os
    agent=pathlib.Path('/opt/nova-node-agent');v=json.loads((agent/'package.json').read_text())['version']
    profiles=json.loads(pathlib.Path('/opt/alirezaserver/compat-profiles.json').read_text())['profiles']
    for item in profiles:
        if item['version']==v and all(hashlib.sha256((agent/name).read_bytes()).hexdigest()==digest for name,digest in item['files'].items()):
            p.write_text(json.dumps({key:item[key] for key in ['version','commit','sha256']}));os.chmod(p,0o600);break
PY
STAGE=runtime-security
python3 "$APP/runtime-upgrade.py" --installed | tee "$WORK/runtime-upgrade.log"
if grep -q '^NODE_RESTART_REQUIRED$' "$WORK/runtime-upgrade.log"; then systemctl restart nova-agent.service; fi
if grep -q '^PHP_RESTART_REQUIRED$' "$WORK/runtime-upgrade.log"; then systemctl try-restart alirezabot-php.service; fi
STAGE=terminal-management
install -m 0755 "$APP/alireza-cli.sh" /usr/local/bin/alireza
if [[ -f /opt/alirezabot/.alirezaserver-managed ]]; then
  STAGE=bot-product-schema
  printf '%s\n' '{"operation":"repair-schema"}' | python3 "$APP/bot-manager.py"
  STAGE=terminal-management
  printf '%s\n' '{"operation":"upgrade-ui"}' | python3 "$APP/bot-manager.py"
  printf '%s\n' '{"operation":"repair-web"}' | python3 "$APP/bot-manager.py"
fi
STAGE=xray-runtime-health
python3 "$APP/xray-access.py"
if ! systemctl is-active --quiet xray.service; then
  systemctl reset-failed xray.service || true
  systemctl restart xray.service
fi
systemctl is-active --quiet xray.service || die 'Xray is still unhealthy; inspect journalctl -u xray.service.'
STAGE=trusted-tls
cat > /etc/systemd/system/alireza-cert-renew.service <<TLS_RENEW_SERVICE
[Unit]
Description=alirezaserver managed IP certificate renewal
After=network-online.target nova-agent.service
[Service]
Type=oneshot
ExecStart=$NODE_BIN /opt/alirezaserver/tls-renew.mjs
TimeoutStartSec=300
UMask=0077
TLS_RENEW_SERVICE
cat > /etc/systemd/system/alireza-cert-renew.timer <<'TLS_RENEW_TIMER'
[Unit]
Description=Check short-lived IP certificate renewal every six hours
[Timer]
OnCalendar=*-*-* 00,06,12,18:00:00
RandomizedDelaySec=900
Persistent=true
[Install]
WantedBy=timers.target
TLS_RENEW_TIMER
systemctl daemon-reload
printf '%s\n' '{"operation":"auto"}' | node "$APP/tls-control.mjs" || die 'Automatic TLS failed for the identity selected in the first Nova prompt. No additional TLS questions were asked. Read alireza support for the exact cause; for a proxied Cloudflare domain, use an already connected DNS token or DNS-only validation.'
STAGE=dns-configuration-repair
for attempt in {1..20}; do
  if curl -fsS --max-time 2 http://127.0.0.1:18085/control/status >/dev/null; then break; fi
  sleep 1
done
# Existing AdGuard configuration is never automatically migrated in 0.6.
log 'AdGuard settings retained; automatic legacy DNS rewriting is disabled.'
dpkg-query -W -f='${Package}\t${Version}\n' openvpn openssl python3 python3-paramiko logrotate > "$ROOT/package-versions.txt"
STAGE=integration-verification
log '[5/5] Verifying the actual panel, branding, OpenVPN and AdGuard through Nova.'
VERIFIED=0
for attempt in {1..12}; do
  if node "$APP/verify-install.mjs" > "$WORK/verify.log" 2>&1; then VERIFIED=1; break; fi
  printf 'Waiting for panel readiness (%s/12)...\n' "$attempt"
  sleep 3
done
cat "$WORK/verify.log"
cp "$WORK/verify.log" "$INSTALL_LOG.verify"; chmod 600 "$INSTALL_LOG.verify"
[[ $VERIFIED == 1 ]] || die 'The integrated panel did not pass verification. Existing add-on data is retained; rerun this file to repair.'
bash "$APP/check.sh"
NOVA_VERSION=$(node -p 'require("/opt/nova-node-agent/package.json").version')
printf '{"version":"0.8.0-rc.14","nova":"%s","adguard":"%s"}\n' "$NOVA_VERSION" "$AG_VERSION" > "$ROOT/installed.json"
install -d /etc/logrotate.d
cat > /etc/logrotate.d/alirezaserver <<'ROTATE'
/var/log/alirezaserver/*.log {
    weekly
    maxsize 2M
    rotate 4
    maxage 30
    missingok
    notifempty
    compress
    delaycompress
    copytruncate
    su root root
}
ROTATE
# OpenVPN status files are overwritten by OpenVPN; service journals use the host policy.
systemctl enable --now alireza-update.timer
rm -f "$ROOT/failed-stage" /var/log/alirezaserver/last-failure.json
HOOK_CHANGED=0
log 'ALIREZASERVER READY — panel branding, OpenVPN management and AdGuard integration verified.'
printf 'نصب پنل alirezaserver و دو بخش AdGuard و OpenVPN تکمیل و بررسی شد.\n'
printf '%s\n' \
 'DNS: AdGuard Home, TCP/UDP 53; owner-only web access through the main panel.' \
 'OpenVPN: create servers/accounts inside Inbounds; legacy URLs remain valid.' \
 'Existing Nova protocols, node enrollment scripts and upstream files are unchanged.' \
 'DNS accepts public clients on your server IPv4:53. Restrict access in AdGuard Access settings if desired.' \
 'A provider firewall/security group must separately allow DNS TCP/UDP 53 and your selected OpenVPN port.' \
 'Rollback add-ons: sudo bash install.sh --rollback' \
 'Diagnostics: sudo bash install.sh --check' \
 'No live multi-node, client-connection or 1 GiB load certification has been performed.'

# Fresh installs finish with the latest compatible official Nova, rather than waiting six hours.
# Release our install lock only after all installer mutations/rollback hooks are complete.
if [[ "$MANAGED" == 0 ]]; then
  flock -u 9
  log 'Checking the latest official Nova after fresh installation.'
  if python3 "$APP/update.py"; then
    log 'Latest compatible Nova check completed.'
  else
    log 'The verified base is retained. See --update-status for the precise update failure.'
  fi
fi
